import{_ as e,c as d,o as a,ae as o}from"./chunks/framework.CFeneB-q.js";const u=JSON.parse('{"title":"移动端 · 入门","description":"","frontmatter":{},"headers":[],"relativePath":"mobile/introduction.md","filePath":"mobile/introduction.md","lastUpdated":1789438865000}'),r={name:"mobile/introduction.md"};function n(i,t,l,c,s,p){return a(),d("div",null,[...t[0]||(t[0]=[o('<h1 id="移动端-·-入门" tabindex="-1">移动端 · 入门 <a class="header-anchor" href="#移动端-·-入门" aria-label="Permalink to &quot;移动端 · 入门&quot;">​</a></h1><blockquote><p>蓝本项目：<code>weChat-applet/delivery-template-uniapp</code>（模板工程，versionName <code>2.4.2</code> / versionCode <code>20402</code>）。客户项目由复制派生（changjin / changshen / qinghua / g108 等）。</p></blockquote><h2 id="平台定位" tabindex="-1">平台定位 <a class="header-anchor" href="#平台定位" aria-label="Permalink to &quot;平台定位&quot;">​</a></h2><p>工地移动端「<strong>4S SiteSecure Mobile</strong>」——E9 工地业务在手机侧的入口，与 PC 端（Keystone 2.0）<strong>同后端、同租户、同权限模型</strong>：</p><ul><li>后端同一套（<code>*.matchbim.cn</code> 体系），移动端接口统一挂在 <code>/app</code> 前缀下；</li><li>登录用户、租户（请求头 <code>tenantId</code>）、按钮权限均由服务端下发，与 PC 端共用权限模型；</li><li>多语言（zh / en）与 PC 端共用词条语义。</li></ul><h2 id="一码多端-微信小程序-app-android" tabindex="-1">一码多端：微信小程序 + App（Android） <a class="header-anchor" href="#一码多端-微信小程序-app-android" aria-label="Permalink to &quot;一码多端：微信小程序 + App（Android）&quot;">​</a></h2><p>uni-app 一套代码编译到微信小程序与 Android App 两个目标，平台差异用条件编译隔离（<code>#ifdef MP-WEIXIN</code> / <code>#ifdef APP-PLUS</code>）：</p><ul><li><strong>App 端原生模块</strong>（manifest <code>app-plus.modules</code>）：Share、Geolocation、Barcode、Camera、iBeacon、Maps、Push（unipush 2，含离线推送）；</li><li><strong>小程序端</strong>：使用微信播放器插件（ezplayer / tplink-player / imou-player，见 manifest <code>mp-weixin.plugins</code>）等微信原生能力；</li><li><strong>发版差异</strong>：App 走整包安装包 + wgt 热更新（<code>utils/version-manager.js</code> + <code>components/app-upgrade</code>）；小程序走版本更新机制（见规范篇<a href="./standards/version-update.html">小程序版本更新</a>）。</li></ul><h2 id="多客户机制-运行时-与-pc-编译期相对" tabindex="-1">多客户机制：运行时（与 PC 编译期相对） <a class="header-anchor" href="#多客户机制-运行时-与-pc-编译期相对" aria-label="Permalink to &quot;多客户机制：运行时（与 PC 编译期相对）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>PC 端（Keystone 2.0）</th><th>移动端（本模板）</th></tr></thead><tbody><tr><td>客户差异实现</td><td>编译期：<code>VITE_BUILD_VIEWS</code> 按客户裁剪业务视图</td><td>运行时：服务端下发菜单树与按钮权限</td></tr><tr><td>请求指向</td><td><code>pnpm switch:api</code> 切换 API 基址</td><td><code>utils/prefix-rules.js</code> 按域名改写 <code>/app</code> 请求前缀（sa / cl 客户）+ 请求头 <code>tenantId</code> / <code>lang</code></td></tr><tr><td>页面</td><td>未选中业务不参与编译</td><td>页面<strong>全量打进 <code>subPages/</code> 分包</strong>，客户 A 的页面代码对客户 B 可见（涉敏感逻辑注意）</td></tr><tr><td>交付方式</td><td>每客户一个仓库副本</td><td>复制模板工程派生 + 服务端配置菜单/权限</td></tr></tbody></table><h2 id="项目族谱" tabindex="-1">项目族谱 <a class="header-anchor" href="#项目族谱" aria-label="Permalink to &quot;项目族谱&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>定位</th><th>状态</th></tr></thead><tbody><tr><td><code>weChat-applet/delivery-template-uniapp</code></td><td>模板工程（母本），新客户项目由复制派生</td><td><strong>主线维护，唯一参考蓝本</strong></td></tr><tr><td>changjin / changshen / qinghua / g108 等</td><td>由模板复制派生的客户项目</td><td>各自维护</td></tr><tr><td>wisdom 系列（changjin / changshen / qinghua / peidianxiang 旧版）</td><td>上一代 Vue2 定制项目</td><td>已停更，勿参考</td></tr><tr><td>beam-wechat</td><td>原生小程序遗留项目</td><td>遗留，勿参考</td></tr><tr><td>i18n-test / uni-forms sample / uni-ui</td><td>demo 试例</td><td>勿参考</td></tr><tr><td>「delivery-template-uniapp - 副本」目录与 <code>.zip</code> 归档</td><td>冗余备份痕迹</td><td>待清理，勿参考</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">模板派生方式现状</p><p>新项目 = 复制整个目录。工作区中已出现整目录复制副本与 200MB+ zip 归档等痕迹，「哪个是权威模板」目前靠团队记忆——模板仓库化（独立 git 仓库 + tag 基线）已列入遗留项（缺口分析 §3.2）。</p></div><h2 id="术语表" tabindex="-1">术语表 <a class="header-anchor" href="#术语表" aria-label="Permalink to &quot;术语表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语</th><th>含义</th></tr></thead><tbody><tr><td>主包 / 分包</td><td>小程序包结构；主包限 2MB，功能页面全部拆进 <code>subPages/</code> 分包</td></tr><tr><td>prefix-rules</td><td><code>utils/prefix-rules.js</code> 的客户域名 → 请求前缀规则表（当前 sa / cl 两客户）</td></tr><tr><td>pap-* 组件</td><td><code>pap-</code> 前缀命名的自研业务组件族（easycom 自动注册）：pap-button、pap-table、pap-navbar 等</td></tr><tr><td>uView（本地迁移版）</td><td>UI 库 uView 2 整体置于 <code>uni_modules/uview-ui</code>，经「全局加载 → 局部加载」迁移改造</td></tr><tr><td>热更新 / 整包更新</td><td>App 两类更新：wgt 热更（不重装）与整包安装包更新</td></tr><tr><td>tenantId / lang</td><td>请求头中的租户与语言标识，运行时多客户的身份载体</td></tr></tbody></table><h2 id="读者指引" tabindex="-1">读者指引 <a class="header-anchor" href="#读者指引" aria-label="Permalink to &quot;读者指引&quot;">​</a></h2><ul><li><strong>新人</strong>：入门 → <a href="./technology-stack.html">技术栈</a> → <a href="./getting-started.html">快速开始</a>（半天内跑起小程序）→ <a href="./project-structure.html">项目结构</a> → <a href="./function-development.html">功能开发</a>；</li><li><strong>只做微信小程序</strong>：跳过快速开始的「App 打包与发布」一节；</li><li><strong>只做 App</strong>：额外细读快速开始的「App 打包与发布」与规范篇「小程序版本更新」；</li><li><strong>从 PC 端转来</strong>：先读上面「多客户机制」对照，理解运行时权限与编译期裁剪的差异；i18n 机制两端完全不同（自研 mixin vs i18next/vue-i18n），见<a href="./technology-stack.html">技术栈</a>。</li></ul><hr><p><strong>负责人</strong>：E9 前端团队 ｜ <strong>最后验证日期</strong>：2026-09-16 ｜ <strong>对应蓝本项目</strong>：<code>delivery-template-uniapp</code>（versionName <code>2.4.2</code>）</p>',19)])])}const g=e(r,[["render",n]]);export{u as __pageData,g as default};
